import {preparePhoto} from './photo-crop.js';
import {fingerprint} from './organiser-utils.js';
import {validatePhoto,uploadPhoto,newRecordID} from './media-rules.js';
import {galleryGroups} from './gallery-groups.js';
export async function compressGalleryPhoto(file){validatePhoto(file);const src=URL.createObjectURL(file);try{const image=new Image();image.src=src;await image.decode();const scale=Math.min(1,1800/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.round(image.naturalWidth*scale);canvas.height=Math.round(image.naturalHeight*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.87));if(!blob)throw Error('Could not prepare '+file.name);return new File([blob],file.name.replace(/\.[^.]+$/,'')+'.webp',{type:'image/webp'});}finally{URL.revokeObjectURL(src);}}
export function galleryTools({host,editor,rows,list,sb,api,status,group,beforeBatch}){
 const selected=new Set();let dragged=null,orderDirty=false,busy=false,queue=[],captionBatch=0;const toolbar=host.querySelector('.collection-toolbar');
 const label=document.createElement('label');label.textContent='Bulk upload · up to 20 photos';const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='image/jpeg,image/png,image/webp';label.append(input);toolbar.append(label);
 const selection=document.createElement('div');selection.className='app-actions gallery-selection';const count=document.createElement('span');count.setAttribute('role','status');count.textContent='0 selected';selection.append(count);const choose=document.createElement('button');choose.type='button';choose.textContent='Select visible';selection.append(choose);const reset=document.createElement('button');reset.type='button';reset.textContent='Clear selection';selection.append(reset);const target=document.createElement('select');target.setAttribute('aria-label','Move selected photos to group');for(const name of galleryGroups){const o=document.createElement('option');o.textContent=name;target.append(o);}selection.append(target);
 const selectionButtons=[];for(const [action,title] of [['publish','Publish selected'],['hide','Hide selected'],['move','Move to group']]){const b=document.createElement('button');b.type='button';b.textContent=title;b.disabled=true;selection.append(b);selectionButtons.push(b);b.onclick=async()=>{if(busy||!selected.size)return;if(orderDirty){status('Save the photo order before changing the selection.',true);return;}if(queue.some(q=>!q.done)){status('Finish or close the upload batch first.',true);return;}if(beforeBatch&&!beforeBatch())return;editor.replaceChildren();if(!confirm(title+' for '+selected.size+' photos?'))return;busy=true;host.inert=true;selection.inert=true;try{const r=await sb.rpc('elan_bulk_gallery',{p_ids:[...selected],p_action:action,p_category:action==='move'?target.value:null});if(r.error)throw r.error;if(r.data?.length!==selected.size)throw Error('The server did not confirm the complete selection. Reload the gallery.');for(const saved of r.data){const i=rows.findIndex(x=>x.id===saved.id);if(i>=0)rows[i]=saved;}selected.clear();list();updateSelection();status(r.data.length+' photos updated.');}catch(e){status(e.message,true);}finally{busy=false;host.inert=false;selection.inert=false;}};}
 function updateSelection(){count.textContent=selected.size+' selected';selectionButtons.forEach(b=>b.disabled=!selected.size);for(const box of host.querySelectorAll('[data-select-photo]'))box.checked=selected.has(box.dataset.selectPhoto);}
 choose.onclick=()=>{for(const box of host.querySelectorAll('[data-select-photo]')){if(selected.size>=200)break;selected.add(box.dataset.selectPhoto);}updateSelection();};reset.onclick=()=>{selected.clear();updateSelection();};toolbar.after(selection);
 const save=document.createElement('button');save.textContent='Save photo order';save.disabled=true;toolbar.append(save);const help=document.createElement('p');help.className='form-note';help.textContent='Drag cards to rearrange them, or use Move earlier / Move later. Then choose Save photo order.';toolbar.after(help);
 const guard=e=>{if(busy||((orderDirty||queue.some(q=>!q.done))&&!confirm('Leave without saving the remaining gallery changes?'))){e.preventDefault();}};const unload=e=>{if(busy||orderDirty||queue.some(q=>!q.done)){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);
 function reorder(from,to){if(busy||from===to)return;const a=rows.findIndex(r=>r.id===from),b=rows.findIndex(r=>r.id===to);if(a<0||b<0)return;const [item]=rows.splice(a,1);rows.splice(b,0,item);orderDirty=true;save.disabled=false;list();status('Order changed in this preview. Save photo order to publish it.');}
 save.onclick=async()=>{busy=true;save.disabled=true;try{const r=await sb.rpc('elan_reorder_gallery',{p_ids:rows.map(r=>r.id)});if(r.error)throw r.error;if(r.data!==rows.length)throw Error('The server did not confirm the new order.');rows.forEach((r,i)=>r.sort_order=i+1);orderDirty=false;status('Photo order saved.');}catch(e){status(e.message,true);}finally{busy=false;save.disabled=!orderDirty;}};
 function clear(){captionBatch++;for(const item of queue){item.captionHelp?.dispose();URL.revokeObjectURL(item.preview);}queue=[];input.value='';}
 input.onchange=async()=>{if(busy||beforeBatch&&!beforeBatch())return;if(orderDirty){status('Save the photo order before uploading.',true);input.value='';return;}if(queue.some(q=>!q.done)&&!confirm('Replace the unsaved upload queue?'))return;const files=[...input.files];try{if(files.length>20)throw Error('Choose up to 20 photos per batch.');files.forEach(validatePhoto);clear();queue=files.map(file=>({id:newRecordID(),file,preview:URL.createObjectURL(file),done:false}));editor.replaceChildren();const form=document.createElement('form');form.className='app-card bulk-gallery';const h=document.createElement('h2');h.textContent='Review your upload batch';form.append(h);const note=document.createElement('p');note.textContent='Choose a group and upload. No captions are needed. Every photo saves as a draft. Select cards to publish a whole batch when ready. Matching file contents are flagged; older uploads may only have a matching filename.';form.append(note);const select=document.createElement('select');select.setAttribute('aria-label','Group for this batch');for(const c of galleryGroups){const o=document.createElement('option');o.value=c;o.textContent=c;select.append(o);}select.value=group?.value||galleryGroups[0];form.append(select);
 for(const item of queue){const row=document.createElement('div');row.className='bulk-photo-row';const image=document.createElement('img');image.src=item.preview;image.alt='Upload preview';row.append(image);const crop=document.createElement('button');crop.type='button';crop.className='secondary';crop.textContent='Crop / frame';row.append(crop);crop.onclick=async()=>{if(busy||item.done||item.uploaded)return;busy=true;form.inert=true;try{const prepared=await preparePhoto(item.file);if(prepared){item.prepared=prepared;item.hash=null;item.duplicateReviewed=false;URL.revokeObjectURL(item.preview);item.preview=URL.createObjectURL(prepared);image.src=item.preview;}}catch(e){item.progress.textContent=e.message;}finally{busy=false;form.inert=false;}};for(const [key,title,max] of [['alt_text','Image description (optional, for accessibility)',400]]){const l=document.createElement('label');l.textContent=title;const field=document.createElement('input');field.required=false;field.maxLength=max;field.value='';item[key]=field; l.append(field);row.append(l);}const skipLabel=document.createElement('label');const skip=document.createElement('input');skip.type='checkbox';skipLabel.append(skip,document.createTextNode(' Skip this photo'));item.skip=skip;row.append(skipLabel);const progress=document.createElement('p');progress.setAttribute('role','status');item.progress=progress;row.append(progress);form.append(row);}
 const meter=document.createElement('progress');meter.max=queue.length;meter.value=0;meter.setAttribute('aria-label','Photos saved or skipped');form.append(meter);const submit=document.createElement('button');submit.type='submit';submit.textContent='Upload as drafts';const cancel=document.createElement('button');cancel.type='button';cancel.className='secondary';cancel.textContent='Close batch';form.append(submit,cancel);cancel.onclick=()=>{if(busy)return;if(queue.some(q=>!q.done)&&!confirm('Discard the photos that have not been saved?'))return;clear();editor.replaceChildren();};
 form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;busy=true;captionBatch++;for(const item of queue)item.captionHelp?.dispose();form.inert=true;let failed=0;for(const item of queue){if(item.done)continue;if(item.skip.checked){item.done=true;item.progress.textContent='Skipped';meter.value=queue.filter(x=>x.done).length;continue;}try{item.progress.textContent='Preparing photo…';item.prepared??=await compressGalleryPhoto(item.file);item.hash??=await fingerprint(item.prepared);if(item.hash&&!item.duplicateReviewed){const existing=await sb.from('elan_photo_fingerprints').select('media_id').eq('sha256',item.hash).limit(1);if(existing.error)throw existing.error;const batchMatch=queue.some(x=>x!==item&&x.hash===item.hash&&x.uploaded);const nameMatch=rows.some(x=>x.title===item.file.name);if(existing.data.length||batchMatch||nameMatch){item.progress.textContent=(existing.data.length||batchMatch?'Matching image contents found.':'A photo with this filename already exists; it may be different.');if(!confirm(item.file.name+': '+item.progress.textContent+' Upload another copy?')){item.skip.checked=true;item.done=true;item.progress.textContent='Duplicate skipped';meter.value=queue.filter(x=>x.done).length;continue;}}item.duplicateReviewed=true;}item.progress.textContent='Uploading…';item.uploaded??=await uploadPhoto(item.prepared,sb,api);const record={id:item.id,edition_slug:'2026',title:item.file.name.slice(0,160)||select.value+' photo',alt_text:item.alt_text.value.trim()||'Élan 2026 · '+select.value+' photograph',image_url:item.uploaded,category:select.value,credit:'',published:false,sort_order:Math.min(9999,Math.max(0,...rows.map(r=>r.sort_order))+1)};const saved=await api('admin-save',{table:'elan_media',record});if(saved.id!==item.id||saved.published!==false)throw Error('Save was not confirmed.');item.done=true;let hashWarning='';if(item.hash){const h=await sb.from('elan_photo_fingerprints').upsert({media_id:item.id,sha256:item.hash});if(h.error)hashWarning=' · duplicate check could not be saved';}item.progress.textContent='Draft saved'+hashWarning;meter.value=queue.filter(x=>x.done).length;item.alt_text.disabled=true;if(!rows.some(r=>r.id===saved.id))rows.push(saved);}catch(err){failed++;item.progress.textContent='Not saved: '+err.message;}}
 busy=false;form.inert=false;submit.disabled=!failed;submit.textContent=failed?'Retry remaining photos':'All drafts saved';list();status(failed?'Some photos need attention. Retry sends only the remaining photos.':'Batch finished. Saved photos are drafts. Select cards to publish them together.',!!failed);};editor.append(form);editor.scrollIntoView({block:'start'});
 }catch(e){status(e.message,true);}};
 return {canLeave(){if(busy)return false;return !(orderDirty||queue.some(q=>!q.done))||confirm('Discard remaining gallery changes?');},decorate(card,row){const pick=document.createElement('label');pick.className='check-row';const box=document.createElement('input');box.type='checkbox';box.dataset.selectPhoto=row.id;box.checked=selected.has(row.id);box.onchange=()=>{if(box.checked){if(selected.size>=200){box.checked=false;status('Select up to 200 photos at a time.',true);return;}selected.add(row.id);}else selected.delete(row.id);updateSelection();};pick.append(box,document.createTextNode('Select photo'));card.prepend(pick);card.draggable=true;card.addEventListener('dragstart',e=>{dragged=row.id;e.dataTransfer.setData('text/plain',row.id);});card.addEventListener('dragover',e=>e.preventDefault());card.addEventListener('drop',e=>{e.preventDefault();if(dragged)reorder(dragged,row.id);dragged=null;});const actions=document.createElement('div');actions.className='app-actions';for(const [label,delta] of [['Move earlier',-1],['Move later',1]]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=label;b.setAttribute('aria-label',label+': '+row.title);b.onclick=()=>{const i=rows.findIndex(r=>r.id===row.id),target=rows[i+delta];if(target)reorder(row.id,target.id)};actions.append(b);}card.append(actions);},dispose(){clear();document.removeEventListener('elan:admin-leave',guard);window.removeEventListener('beforeunload',unload);},canEdit(){if(busy)return false;if(orderDirty){status('Save the photo order before editing an entry.',true);return false;}if(queue.some(q=>!q.done)&&!confirm('Discard the remaining upload queue?'))return false;clear();return true;}};
}
